//! Deterministic network-identity derivation — bit-for-bit compatible with the Go
//! module's `src/identity`.
//!
//! WHY THIS MODULE EXISTS: both modules read the same `identities.json`
//! (`owned_identities[0].privatekey`). A router must show the SAME npub, the same
//! CGNAT IPv4, the same per-interface MACs and the same recovery passwords
//! whichever module is deployed — otherwise "restore from identities.json" is not
//! an interop path but a coin flip.
//!
//! The Go ground truth this must reproduce byte-for-byte was generated by running
//! the Go package itself (`go run` against
//! `github.com/OpenTollGate/tollgate-module-basic-go/src/identity`), not by reading
//! the code and hoping. Vectors live in the tests below.

use hmac::{Hmac, Mac};
use sha2::{Digest, Sha256};

type HmacSha256 = Hmac<Sha256>;

/// The interfaces the Go module derives MACs for, in its order.
pub const STANDARD_INTERFACES: [&str; 3] = ["br-lan", "wlan0", "wlan1"];

/// HKDF as the Go module calls it: `hkdf.Key(sha256.new, secret=key, salt="tollgate-v1",
/// info=domainSep, length=32)`.
///
/// Go's `crypto/hkdf.Key(h, secret, salt, info, keyLength)` argument order is
/// (hash, secret, salt, info, length) — the Rust `hkdf` crate's `Hkdf::new(salt, ikm)`
/// plus `expand(info)` matches exactly, but this is THE place a port can silently
/// diverge, so the domain separators and salt are asserted in tests against Go output.
/// HKDF-Expand per RFC 5869, HMAC-SHA256, implemented directly on `hmac` + `sha2`
/// so crate-version drift cannot silently change the derivation. Output = 32 bytes
/// = exactly one HMAC block, so the RFC's single-iteration path applies.
fn derive_hash(domain_sep: &str, key_hex: &str) -> [u8; 32] {
    // Extract: PRK = HMAC-SHA256(salt="tollgate-v1", IKM=key_hex)
    let mut mac =
        <HmacSha256 as Mac>::new_from_slice(b"tollgate-v1").expect("HMAC accepts any key length");
    mac.update(key_hex.as_bytes());
    let prk = mac.finalize().into_bytes();

    // Expand: T(1) = HMAC(PRK, info || 0x01); 32 <= hash len, so one block suffices.
    let mut mac = <HmacSha256 as Mac>::new_from_slice(&prk).expect("PRK is 32 bytes");
    mac.update(domain_sep.as_bytes());
    mac.update(&[0x01]);
    let t1 = mac.finalize().into_bytes();

    let mut out = [0u8; 32];
    out.copy_from_slice(&t1);
    out
}

/// Validate a hex secp256k1 private key (64 hex chars, a valid scalar) — the Go
/// module's `validatePrivKeyHex`.
pub fn validate_priv_key_hex(hex_key: &str) -> Result<(), String> {
    let bytes =
        hex::decode(hex_key).map_err(|e| format!("identity: private key is not valid hex: {e}"))?;
    if bytes.len() != 32 {
        return Err(format!(
            "identity: private key is {} bytes, want 32",
            bytes.len()
        ));
    }
    // secp256k1 scalar validity (nonzero, < curve order) — the Go module relies on
    // nostr.GetPublicKey's validation, which rejects zero and order-overflowing keys.
    use secp256k1::SecretKey;
    SecretKey::from_slice(&bytes)
        .map_err(|e| format!("identity: private key is not a usable scalar: {e}"))?;
    Ok(())
}

/// Public key as 64-char x-only hex — go-nostr's `GetPublicKey` returns the BIP340
/// x-only form (32 bytes, no 02/03 prefix), NOT the 33-byte compressed form. Getting
/// this wrong silently changes every downstream derivation (measured: first port
/// attempt produced different IPv4/MACs/npub from Go for the same key).
pub fn public_key_hex(hex_priv: &str) -> Result<String, String> {
    validate_priv_key_hex(hex_priv)?;
    let sk_bytes = hex::decode(hex_priv).map_err(|e| e.to_string())?;
    use secp256k1::{PublicKey, SecretKey};
    let sk = SecretKey::from_slice(&sk_bytes).map_err(|e| e.to_string())?;
    let pk = PublicKey::from_secret_key(secp256k1::SECP256K1, &sk);
    let compressed = pk.serialize(); // 33 bytes: [0x02|0x03, x..]
    Ok(hex::encode(&compressed[1..])) // x-only, go-nostr's form
}

/// bech32 npub1… encoding of the public key — Go's `nip19.EncodePublicKey(pubHex)`.
pub fn npub_from_private_key(hex_priv: &str) -> Result<String, String> {
    let pub_hex = public_key_hex(hex_priv)?;
    let bytes = hex::decode(&pub_hex).map_err(|e| e.to_string())?;
    bech32::encode::<bech32::Bech32>(
        bech32::Hrp::parse("npub").map_err(|e| format!("npub hrp: {e}"))?,
        &bytes,
    )
    .map_err(|e| format!("identity: encode npub: {e}"))
    .map_err(|e| format!("identity: encode npub: {e}"))
}

/// Map the public key into RFC 6598 CGNAT (100.64.0.0/10), host octet .1 —
/// Go's `DeriveIPv4`: octet2 = 64 + (h[0] % 64), octet3 = h[1], octet4 = 1.
pub fn derive_ipv4(pub_key_hex: &str) -> String {
    let h = derive_hash("tollgate-ipv4-v1:", pub_key_hex);
    let octet2 = 64 + (h[0] % 64) as u32;
    let octet3 = h[1] as u32;
    format!("100.{octet2}.{octet3}.1")
}

/// Locally-administered unicast MAC per interface — Go's `DeriveMAC`: first octet
/// gets bit 1 set and bit 0 cleared (0x02 | ...), rest from the hash.
pub fn derive_mac(pub_key_hex: &str, iface: &str) -> String {
    let h = derive_hash(&format!("tollgate-mac-v1:{iface}:"), pub_key_hex);
    let mut mac = [0u8; 6];
    mac.copy_from_slice(&h[..6]);
    mac[0] = (mac[0] | 0x02) & !0x01; // locally administered, unicast
    format!(
        "{:02x}:{:02x}:{:02x}:{:02x}:{:02x}:{:02x}",
        mac[0], mac[1], mac[2], mac[3], mac[4], mac[5]
    )
}

/// The BIP39 English word list, extracted from the exact library the Go module
/// uses (tyler-smith/go-bip39@v1.1.0) via `go run` — not retyped, not from memory.
const BIP39_ENGLISH_RAW: &str = include_str!("bip39_english.txt");

fn word_list() -> Vec<&'static str> {
    BIP39_ENGLISH_RAW
        .lines()
        .map(|l| l.trim())
        .filter(|l| !l.is_empty())
        .collect()
}

/// Lazily-built word list for the password derivations.
static WORD_LIST: std::sync::OnceLock<Vec<&'static str>> = std::sync::OnceLock::new();
pub fn words() -> &'static Vec<&'static str> {
    WORD_LIST.get_or_init(word_list)
}

/// 6 BIP39 words joined by "-", indices = big-endian u16 pairs mod 2048 — Go's
/// `DeriveRootPassword` / `DeriveWiFiPassword` shape.
fn words_from_hash(h: &[u8; 32], words: &[&str]) -> String {
    let mut parts: Vec<&str> = Vec::with_capacity(6);
    for i in 0..6 {
        let idx = ((h[i * 2] as usize) << 8 | (h[i * 2 + 1] as usize)) % words.len();
        parts.push(words[idx]);
    }
    parts.join("-")
}

pub fn derive_root_password(hex_priv: &str) -> String {
    let h = derive_hash("tollgate-root-pw-v2:", hex_priv);
    words_from_hash(&h, words())
}

pub fn derive_wifi_password(hex_priv: &str, network: &str) -> String {
    let h = derive_hash(&format!("tollgate-wifi-pw-v2:{network}:"), hex_priv);
    words_from_hash(&h, words())
}

/// The public, non-sensitive identity — GET /identity.
#[derive(Debug, Clone, serde::Serialize)]
pub struct DerivedIdentity {
    pub npub: String,
    pub ipv4: String,
    pub macs: std::collections::BTreeMap<String, String>,
}

pub fn derive(hex_priv: &str) -> Result<DerivedIdentity, String> {
    validate_priv_key_hex(hex_priv)?;
    let pub_hex = public_key_hex(hex_priv)?;
    let mut macs = std::collections::BTreeMap::new();
    for iface in STANDARD_INTERFACES {
        macs.insert(iface.to_string(), derive_mac(&pub_hex, iface));
    }
    Ok(DerivedIdentity {
        npub: npub_from_private_key(hex_priv)?,
        ipv4: derive_ipv4(&pub_hex),
        macs,
    })
}

#[cfg(test)]
mod tests {
    use super::*;

    /// The Go module run directly, 2026-10-20 — the interop contract.
    const GO_VECTORS: &str = r#"{"ipv4":"100.122.116.1","macs":{"br-lan":"86:29:f5:dc:a9:ce","wlan0":"46:c8:01:38:dc:30","wlan1":"96:96:89:ec:79:58"},"npub":"npub1gyeral42hsava72sh23rtckfhqrugpcnlx5scs4ldfmh68u7ksfq0au6p2","root":"like-runway-random-blush-timber-lamp","wifi":"address-tail-essence-client-upper-license"}"#;
    const TEST_KEY: &str = "d1a1ff3ac0ffee00000000000000000000000000000000000000000000000000";

    #[test]
    fn go_vectors_reproduce_bit_for_bit() {
        let d = derive(TEST_KEY).expect("derive");
        assert_eq!(d.ipv4, "100.122.116.1");
        assert_eq!(
            d.npub,
            "npub1gyeral42hsava72sh23rtckfhqrugpcnlx5scs4ldfmh68u7ksfq0au6p2"
        );
        assert_eq!(d.macs.get("br-lan").unwrap(), "86:29:f5:dc:a9:ce");
        assert_eq!(d.macs.get("wlan0").unwrap(), "46:c8:01:38:dc:30");
        assert_eq!(d.macs.get("wlan1").unwrap(), "96:96:89:ec:79:58");
        assert_eq!(
            derive_root_password(TEST_KEY),
            "like-runway-random-blush-timber-lamp"
        );
        assert_eq!(
            derive_wifi_password(TEST_KEY, "private"),
            "address-tail-essence-client-upper-license"
        );
        let _ = GO_VECTORS; // reference: the JSON the Go binary printed
    }

    #[test]
    fn odd_or_short_keys_are_rejected() {
        assert!(validate_priv_key_hex("abc").is_err());
        assert!(validate_priv_key_hex("00").is_err()); // zero scalar (1 byte, padded)
        assert!(validate_priv_key_hex(&"f".repeat(64)).is_err()); // overflow scalar? actually f..f > n
    }
}
